  "App Raccourcis → « + » → nommez le raccourci « Envoyer à Pécule ».": "App Comandi Rapidi → «+» → chiama il comando rapido «Invia a Pécule».",
  "Réglages du raccourci (ⓘ) : activez « Afficher dans la feuille de partage », types acceptés : Fichiers, PDF, Images.": "Impostazioni del comando rapido (ⓘ): attiva «Mostra nel foglio di condivisione», tipi accettati: File, PDF, Immagini.",
  "Ajoute l'action « Obtenir le contenu de l'URL » :": "Aggiungi l'azione «Ottieni contenuti dell'URL»:",
  "(après « name= », insérez la variable « Entrée du raccourci → Nom »).": "(dopo «name=», inserisci la variabile «Input comando rapido → Nome»).",
  "Méthode POST ; en-tête « Authorization » = le jeton copié (« Bearer pec_… ») ; corps de la requête : Fichier → « Entrée du raccourci ».": "Metodo POST; intestazione «Authorization» = il token copiato («Bearer pec_…»); corpo della richiesta: File → «Input comando rapido».",
  "Ajoute « Afficher la notification » avec le résultat (titre du document rangé).": "Aggiungi «Mostra notifica» con il risultato (titolo del documento archiviato).",
