  "Oublier ce fait": "Dimentica questo fatto",
  "Rien pour l'instant. Dis par exemple à l'assistant « souviens-toi que… » ; il retient aussi de lui-même ce que tu lui expliques (contexte, prélèvements, préférences).": "Niente per ora. Di' per esempio all'assistente «ricordati che…»; ricorda anche da solo ciò che gli spieghi (contesto, addebiti diretti, preferenze).",
  "Ces faits sont propres à chaque membre et joints aux consignes de l'assistant à chaque conversation.": "Questi fatti sono propri di ciascun membro e vengono aggiunti alle istruzioni dell'assistente a ogni conversazione.",
  "Garde sur cet appareil les dernières données de synthèse (soldes, mois, patrimoine, budget, opérations récentes) 7 jours au plus : l'appli s'ouvre tout de suite, même sans réseau. Effacées à la déconnexion ; jamais les factures, documents ni conversations.": "Conserva su questo dispositivo gli ultimi dati di sintesi (saldi, mese, patrimonio, budget, movimenti recenti) per 7 giorni al massimo: l'app si apre subito, anche senza rete. Cancellati alla disconnessione; mai le fatture, i documenti né le conversazioni.",
  "Données effacées de cet appareil": "Dati cancellati da questo dispositivo",
  "Actif au prochain lancement de l'appli": "Attivo al prossimo avvio dell'app",
  "Un nouveau lien remplace l'ancien : les agendas abonnés à l'ancien ne se mettront plus à jour. Continuer ?": "Un nuovo link sostituisce il vecchio: i calendari abbonati al vecchio non si aggiorneranno più. Continuare?",
  "Couper l'abonnement ? Les agendas abonnés ne recevront plus l'échéancier.": "Interrompere l'abbonamento? I calendari abbonati non riceveranno più lo scadenzario.",
  "Échéancier dans Calendrier": "Scadenzario in Calendario",
  "Abonne Calendrier (iPhone, Mac) à ton échéancier : tâches, mensualités, fins de crédit, garanties, documents qui expirent, calendrier fiscal, avec un rappel la veille. Mis à jour toutes les 6 heures ; le lien est privé, garde-le pour toi.": "Abbona Calendario (iPhone, Mac) al tuo scadenzario: attività, rate mensili, fine dei prestiti, garanzie, documenti in scadenza, calendario fiscale, con un promemoria il giorno prima. Aggiornato ogni 6 ore; il link è privato, tienilo per te.",
  "Copie ce lien maintenant : il ne sera plus affiché.": "Copia questo link adesso: non verrà più mostrato.",
  "S'abonner sur cet appareil": "Abbonati su questo dispositivo",
  "Copier le lien": "Copia il link",
