  "Nouveau lien": "Nuovo link",
  "Couper##abonnement": "Interrompi",
  "Créer le lien d'abonnement": "Crea il link di abbonamento",
  "{quoi} : indisponible en mode démo (rien ne doit toucher à tes vrais appareils ni à tes vrais accès).": "{quoi}: non disponibile in modalità demo (niente deve toccare i tuoi veri dispositivi né i tuoi veri accessi).",
  "Mode démo actif": "Modalità demo attiva",
  "Données fictives. Touche pour en sortir.": "Dati fittizi. Tocca per uscire.",
  "Le mode démo est actif.": "La modalità demo è attiva.",
  "Tout ce que tu vois est fictif : la famille, les comptes, les opérations, les factures, le patrimoine. Tes vraies données restent cachées.": "Tutto ciò che vedi è fittizio: la famiglia, i conti, i movimenti, le fatture, il patrimonio. I tuoi dati veri restano nascosti.",
  "Sortie impossible": "Impossibile uscire",
  "Vérification…": "Verifica…",
  "Quitter le mode démo": "Esci dalla modalità demo",
  "Face ID, Touch ID ou le code de l'appareil est demandé : personne ne peut sortir de la démo à ta place.": "Viene richiesto Face ID, Touch ID o il codice del dispositivo: nessuno può uscire dalla demo al posto tuo.",
  "Montre Pécule sans rien dévoiler : l'appli passe sur une famille imaginaire, avec ses comptes, ses opérations, ses factures, son patrimoine et son échéancier. Tout fonctionne, l'assistant compris, mais sur ces données fictives.": "Mostra Pécule senza svelare nulla: l'app passa a una famiglia immaginaria, con i suoi conti, i suoi movimenti, le sue fatture, il suo patrimonio e il suo scadenzario. Funziona tutto, assistente compreso, ma su questi dati fittizi.",
  "Sur cet appareil seulement : les autres membres et tes autres appareils restent sur les vraies données.": "Solo su questo dispositivo: gli altri membri e i tuoi altri dispositivi restano sui dati veri.",
  "Pour revenir à tes données : Face ID ou Touch ID.": "Per tornare ai tuoi dati: Face ID o Touch ID.",
  "Synchronisation, notifications et clés d'accès sont coupées pendant la démo ; les données fictives sont remises à neuf chaque jour.": "Sincronizzazione, notifiche e passkey sono disattivate durante la demo; i dati fittizi vengono rigenerati ogni giorno.",
  "Mode démo indisponible": "Modalità demo non disponibile",
  "Préparation de la démo…": "Preparazione della demo…",
  "Passer en mode démo": "Passa alla modalità demo",
  "Mode démo non configuré": "Modalità demo non configurata",
  "Réglage indisponible": "Impostazione non disponibile",
  "Réglage commun à toute la famille. Le fournisseur choisi reçoit tout ce que Pécule confie à l'IA : questions à l'assistant, factures, documents et bulletins de paie. Les clés sont chiffrées et ne sont plus jamais affichées. Un fournisseur est essayé avant d'être choisi ou modifié : si l'essai échoue, rien ne change.": "Impostazione comune a tutta la famiglia. Il fornitore scelto riceve tutto ciò che Pécule affida all'IA: domande all'assistente, fatture, documenti e buste paga. Le chiavi sono cifrate e non vengono mai più mostrate. Un fornitore viene provato prima di essere scelto o modificato: se la prova fallisce, non cambia nulla.",
  "Le mode vocal passe toujours par la ressource Microsoft Foundry.": "La modalità vocale passa sempre dalla risorsa Microsoft Foundry.",
  "Le mode vocal a besoin d'une ressource Microsoft Foundry (son nom et sa clé).": "La modalità vocale ha bisogno di una risorsa Microsoft Foundry (il suo nome e la sua chiave).",
  "Utilisé##fournisseur": "In uso",
  "Choisi, incomplet": "Scelto, incompleto",
  "Prêt##fournisseur": "Pronto",
