  "L'essai a échoué": "La prova è fallita",
  "Essai impossible": "Prova non riuscita",
  "Confier l'IA de Pécule à « {nom} » ? Les questions à l'assistant, les factures, les documents et les bulletins de paie lui seront envoyés.": "Affidare l'IA di Pécule a «{nom}»? Le domande all'assistente, le fatture, i documenti e le buste paga gli saranno inviati.",
  "{nom} répond maintenant": "Ora risponde {nom}",
  "Retirer la clé enregistrée ici ? Celle de l'hébergement reprendra la main, s'il y en a une.": "Rimuovere la chiave salvata qui? Quella dell'hosting tornerà a valere, se ce n'è una.",
  "Retirer la clé enregistrée pour ce fournisseur ?": "Rimuovere la chiave salvata per questo fornitore?",
  "Clé retirée": "Chiave rimossa",
  "La clé enregistrée n'est plus lisible (le secret du serveur a changé) : ressaisis-la.": "La chiave salvata non è più leggibile (il segreto del server è cambiato): inseriscila di nuovo.",
