  "Autorisation refusée : active les notifications de Pécule dans les réglages de l'appareil.": "Autorizzazione negata: attiva le notifiche di Pécule nelle impostazioni del dispositivo.",
  "Notifications activées sur cet appareil": "Notifiche attivate su questo dispositivo",
