  "Notifications désactivées sur cet appareil": "Notifiche disattivate su questo dispositivo",
  "Pour recevoir les notifications sur l'iPhone, installe d'abord Pécule sur l'écran d'accueil (Partager → Sur l'écran d'accueil), puis ouvre l'appli depuis son icône et reviens ici.": "Per ricevere le notifiche sull'iPhone, installa prima Pécule sulla schermata Home (Condividi → Aggiungi alla schermata Home), poi apri l'app dalla sua icona e torna qui.",
  "Ce navigateur ne gère pas les notifications.": "Questo browser non supporta le notifiche.",
  "Reçois sur cet appareil les alertes utiles : opérations à classer, prélèvement nouveau ou inhabituel, solde bas, loyer non reçu, échéances, garanties, enveloppes, et le résumé de la semaine.": "Ricevi su questo dispositivo gli avvisi utili: movimenti da classificare, addebito diretto nuovo o insolito, saldo basso, affitto non ricevuto, scadenze, garanzie, buste e il riepilogo della settimana.",
  "Activer sur cet appareil": "Attiva su questo dispositivo",
  "Notification d'essai envoyée": "Notifica di prova inviata",
  "Aucun appareil n'a reçu l'essai": "Nessun dispositivo ha ricevuto la prova",
  "Essai": "Prova",
  "Désactiver sur cet appareil": "Disattiva su questo dispositivo",
  "Dernières notifications": "Ultime notifiche",
  "Import impossible": "Impossibile importare",
  "Sur BoursoBank : {lien}, tous les comptes, format CSV. Tu peux redéposer le même fichier : rien n'est compté deux fois, et un nom déjà posé n'est jamais remplacé.": "Su BoursoBank: {lien}, tutti i conti, formato CSV. Puoi caricare di nuovo lo stesso file: niente viene contato due volte e un nome già assegnato non viene mai sostituito.",
  "Pour un prélèvement ou un virement, la synchronisation ne transmet souvent qu'une référence. L'export de BoursoBank porte le nom du créancier : dépose-le ici pour nommer ces opérations et les classer comme celles du même nom.": "Per un addebito diretto o un bonifico, la sincronizzazione trasmette spesso solo un riferimento. L'esportazione di BoursoBank riporta il nome del creditore: caricala qui per dare un nome a questi movimenti e classificarli come quelli con lo stesso nome.",
  "Import en cours…": "Importazione in corso…",
  "Déposer l'export CSV": "Carica l'esportazione CSV",
  "Équivalences amusantes": "Equivalenze divertenti",
  "Pendant un thème, les dépenses se lisent aussi dans l'unité du moment (litres de bière à la Saint-Patrick, kilos de bonbons à Halloween…) et, toute l'année, en temps de travail d'après tes bulletins de paie. Avec, sur l'accueil, « Le chiffre du moment » et ce que coûte la fête en cours. Aucun montant ne change. Valable sur tous tes appareils, assistant compris.": "Durante un tema, le spese si leggono anche nell'unità del momento (litri di birra a San Patrizio, chili di caramelle a Halloween…) e, tutto l'anno, in tempo di lavoro in base alle tue buste paga. In più, nella Home, «La cifra del momento» e quanto costa la festa in corso. Nessun importo cambia. Vale su tutti i tuoi dispositivi, assistente compreso.",
  "En ce moment ({theme}) : {unite}, soit 100 € ≈ {equivalent}.": "In questo momento ({theme}): {unite}, quindi 100 € ≈ {equivalent}.",
  "En ce moment ({theme}) : {unite}.": "In questo momento ({theme}): {unite}.",
  "Équivalences activées": "Equivalenze attivate",
  "Équivalences désactivées": "Equivalenze disattivate",
  "Logo": "Logo",
  "Le coffre de tous les jours, sur le fond de ton choix. Dans l'appli et dans l'onglet du navigateur, il prend tout seul le décor du thème du moment (en ce moment : {theme}).": "Lo scrigno di tutti i giorni, sullo sfondo che preferisci. Nell'app e nella scheda del browser prende da solo la decorazione del tema del momento (in questo momento: {theme}).",
  "Le coffre de tous les jours, sur le fond de ton choix. Dans l'appli et dans l'onglet du navigateur, il prend tout seul le décor du thème du moment.": "Lo scrigno di tutti i giorni, sullo sfondo che preferisci. Nell'app e nella scheda del browser prende da solo la decorazione del tema del momento.",
  "Icône sur l'écran d'accueil": "Icona sulla schermata Home",
  "Comme le logo": "Come il logo",
  "L'iPhone garde l'icône du jour où Pécule a été ajouté à l'écran d'accueil : elle ne peut pas changer toute seule. Pour en changer, ouvre Pécule dans Safari, choisis l'icône ici, supprime l'ancienne de l'écran d'accueil, puis Partager → « Sur l'écran d'accueil ». Il faudra te reconnecter et réactiver les notifications.": "L'iPhone conserva l'icona del giorno in cui Pécule è stato aggiunto alla schermata Home: non può cambiare da sola. Per cambiarla, apri Pécule in Safari, scegli l'icona qui, elimina la vecchia dalla schermata Home, poi Condividi → «Aggiungi alla schermata Home». Dovrai accedere di nuovo e riattivare le notifiche.",
  "Tu es dans l'appli installée : fais ce choix depuis Safari, c'est lui qui crée l'icône.": "Sei nell'app installata: fai questa scelta da Safari, è lui che crea l'icona.",
