  "Fixe un plafond mensuel par poste (Alimentation, Restaurants…) : la jauge se remplit au fil du mois, l'alerte tombe à 80 %. Pécule propose la moyenne de tes 3 derniers mois.": "Fissa un tetto mensile per voce (Alimentazione, Ristoranti…): l'indicatore si riempie nel corso del mese e l'avviso arriva all'80%. Pécule propone la media dei tuoi ultimi 3 mesi.",
