  "aucune date fixée": "nessuna data fissata",
  "Tes objectifs": "I tuoi obiettivi",
  "Un objectif = un projet (voyage, travaux, voiture, apport…), un montant et une date. Relie-le à un livret ou un placement : l'avancement suit sa valeur, et Pécule calcule le versement mensuel pour tenir la date.": "Un obiettivo = un progetto (viaggio, lavori, auto, anticipo…), un importo e una data. Collegalo a un libretto o a un investimento: l'avanzamento segue il suo valore e Pécule calcola il versamento mensile per rispettare la data.",
