  "{n} seulement à la banque, dont {attente} en attente de prélèvement": "{n} solo in banca, di cui {attente} in attesa di addebito",
  "{n} seulement dans Pécule": "{n} solo in Pécule",
  "« Datées autrement » : des achats de fin de mois que la banque prélève un mois plus tard que ce que Pécule supposait. La date de la banque fera foi.": "«Datati diversamente»: acquisti di fine mese che la banca addebita un mese più tardi di quanto Pécule supponeva. Farà fede la data della banca.",
  "Comparer avec mes comptes actuels": "Confronta con i miei conti attuali",
  "Accord bancaire à renouveler · {banque}": "Consenso bancario da rinnovare · {banque}",
  "Ta clé personnelle": "La tua chiave personale",
  "Oublier ma clé": "Dimentica la mia chiave",
  "Oublier ta clé personnelle et tes accords ? Les opérations déjà lues restent dans Pécule.": "Dimenticare la tua chiave personale e i tuoi consensi? I movimenti già letti restano in Pécule.",
  "J'ai des comptes à mon seul nom": "Ho dei conti intestati solo a me",
  "L'usage gratuit d'Enable Banking ne couvre que les comptes de la personne inscrite. Si tu as des comptes à ton seul nom, crée ta propre application sur enablebanking.com et donne ici sa clé : elle servira à tes accords.": "L'uso gratuito di Enable Banking copre solo i conti della persona registrata. Se hai dei conti intestati solo a te, crea la tua applicazione su enablebanking.com e inserisci qui la sua chiave: servirà per i tuoi consensi.",
  "Synchronisations bancaires": "Sincronizzazioni bancarie",
  "alertes techniques journal audit synchronisation banque": "avvisi tecnici registro audit sincronizzazione banca",
  "Synchroniser les comptes bancaires": "Sincronizza i conti bancari",
  "Compte importé": "Conto importato",
  "Dépose l'export de ta banque (OFX, QIF ou CSV) : ses opérations rejoignent le compte choisi. Tu peux redéposer un fichier qui recouvre le précédent, rien n'est ajouté deux fois.": "Deposita l'esportazione della tua banca (OFX, QIF o CSV): i suoi movimenti entrano nel conto scelto. Puoi depositare un file che si sovrappone al precedente: nulla viene aggiunto due volte.",
  "Nouveau compte…": "Nuovo conto…",
