  "Bienvenue dans Pécule": "Benvenuto in Pécule",
  "Cette installation est neuve. Crée le premier membre du foyer : il en sera l'administrateur.": "Questa installazione è nuova. Crea il primo membro della famiglia: ne sarà l'amministratore.",
