  "Ce prénom est déjà pris.": "Questo nome è già in uso.",
  "Membre ajouté : envoie-lui son lien d'inscription.": "Membro aggiunto: inviagli il suo link di iscrizione.",
  "Prénom du nouveau membre": "Nome del nuovo membro",
  "Ajouter un membre": "Aggiungi un membro",
  "Par l'interface officielle de ta banque, en lecture seule (Enable Banking, gratuit pour un usage personnel).": "Tramite l'interfaccia ufficiale della tua banca, in sola lettura (Enable Banking, gratuito per uso personale).",
  "Importer un fichier de ta banque": "Importa un file della tua banca",
  "L'export OFX, QIF ou CSV de ton espace client : aucun service à relier.": "L'esportazione OFX, QIF o CSV della tua area clienti: nessun servizio da collegare.",
  "Brancher l'assistant": "Collega l'assistente",
  "Facultatif : avec ta propre clé d'IA, Pécule lit tes factures et répond à tes questions.": "Facoltativo: con la tua chiave di IA, Pécule legge le tue fatture e risponde alle tue domande.",
  "Bien démarrer": "Per iniziare",
  "Pécule est installé et ton foyer est créé. Donne-lui ses premières opérations : tout le reste en découle.": "Pécule è installato e la tua famiglia è creata. Dagli i primi movimenti: tutto il resto ne deriva.",
  "Voir Pécule rempli, avec une famille fictive": "Vedi Pécule pieno, con una famiglia fittizia",
  "Écrans affichés": "Schermate visualizzate",
  "Un écran retiré sort du menu, de la recherche et des raccourcis pour tout le foyer. Ses données restent en place : le remettre les retrouve telles quelles.": "Una schermata rimossa esce dal menu, dalla ricerca e dalle scorciatoie per tutta la famiglia. I suoi dati restano al loro posto: rimettendola li ritrovi tali e quali.",
  "Seul l'administrateur du foyer peut changer ces réglages.": "Solo l'amministratore della famiglia può cambiare queste impostazioni.",
  "Personnes et banques": "Persone e banche",
  "Personnes sans connexion": "Persone senza accesso",
  "Un enfant, par exemple : ses comptes portent son prénom et lui sont attribués. Sépare les prénoms par une virgule.": "Un figlio, per esempio: i conti che portano il suo nome gli vengono attribuiti. Separa i nomi con una virgola.",
  "Banques des comptes professionnels": "Banche dei conti professionali",
  "Nom de la banque": "Nome della banca",
  "Les comptes de ces banques sont rangés à part, masqués et hors statistiques dès leur arrivée.": "I conti di queste banche sono tenuti a parte, nascosti ed esclusi dalle statistiche fin dal loro arrivo.",
  "Foyer enregistré": "Famiglia salvata",
  "Biens, valeur, loyers, taxe foncière": "Immobili, valore, affitti, imposta fondiaria",
  "Positions, cours, journal des mouvements": "Posizioni, quotazioni, registro dei movimenti",
  "Scénarios de patrimoine à plusieurs années": "Scenari di patrimonio su più anni",
  "Bulletins de paie, sources de revenus": "Buste paga, fonti di reddito",
  "Impôt sur le revenu, taxes foncières": "Imposta sul reddito, imposte fondiarie",
  "Carrière, trimestres, estimations": "Carriera, trimestri, stime",
  "L'assistant n'est pas branché": "L'assistente non è collegato",
  "Pécule fonctionne sans IA : seules la lecture automatique des factures et des documents et les réponses à tes questions en dépendent. Pour les activer, ajoute la clé de ton fournisseur d'IA.": "Pécule funziona senza IA: ne dipendono solo la lettura automatica di fatture e documenti e le risposte alle tue domande. Per attivarle, aggiungi la chiave del tuo fornitore di IA.",
  "Réglages → Assistant": "Impostazioni → Assistente",
  "Opération ajoutée": "Movimento aggiunto",
  "Ajouter une opération": "Aggiungi un movimento",
  "Dépense": "Spesa",
  "Revenu": "Entrata",
  "Boulangerie, loyer, salaire…": "Panetteria, affitto, stipendio…",
  "L'opération est classée comme les autres (règles, libellés déjà classés) ; tu peux ensuite changer sa catégorie. Si le compte a un solde, il suit.": "Il movimento viene classificato come gli altri (regole, causali già classificate); puoi poi cambiarne la categoria. Se il conto ha un saldo, viene aggiornato.",
  "Ajouter l'opération": "Aggiungi il movimento",
