  "Seule une opération saisie à la main peut être supprimée.": "Solo un movimento inserito a mano può essere eliminato.",
  "Créer un compte à la main": "Crea un conto a mano",
  "Solde illisible": "Saldo illeggibile",
  "Compte créé": "Conto creato",
  "Un compte tenu à la main : aucune banque ne l'alimente, tu y ajoutes ses opérations (écran Opérations) ou tu y importes un fichier.": "Un conto tenuto a mano: nessuna banca lo alimenta, vi aggiungi i suoi movimenti (schermata Movimenti) o vi importi un file.",
  "Créer le compte": "Crea il conto",
  "Importer des documents": "Importa documenti",
  "importer dossier documents lot bulletins avis releves depot massif": "importare cartella documenti lotto buste paga avvisi estratti caricamento massivo",
  "Fichiers du {date}": "File del {date}",
  "Glisse ici un dossier ou des fichiers": "Trascina qui una cartella o dei file",
  "Préparation des fichiers… {a} sur {b}": "Preparazione dei file… {a} di {b}",
  "Envoi… {a} sur {b}": "Invio… {a} di {b}",
  "Choisir un dossier": "Scegli una cartella",
  "Choisir des fichiers": "Scegli dei file",
  "Chaque fichier est rangé au coffre. Ceux que Pécule sait lire donnent une proposition, que tu relis avant qu'elle ne soit écrite dans tes écrans ; tout import peut être annulé. La lecture passe par ton fournisseur d'IA : le coût est estimé avant, mesuré ensuite, et plafonné par lot.": "Ogni file viene archiviato nella cassaforte. Quelli che Pécule sa leggere danno una proposta, che rivedi prima che venga scritta nelle tue schermate; ogni importazione può essere annullata. La lettura passa dal tuo fornitore di IA: il costo è stimato prima, misurato dopo e limitato per lotto.",
