  "Les montants saisis à la main (budgets, objectifs, placements, biens, crédits, bulletins) gardent leur chiffre : à revoir ensuite.": "Gli importi inseriti a mano (budget, obiettivi, investimenti, immobili, prestiti, buste paga) mantengono la loro cifra: da rivedere dopo.",
