  "Fuseau horaire enregistré": "Fuso orario salvato",
  "Un compte tenu dans une autre devise garde ses montants d'origine ; ils sont convertis au cours de référence de la Banque centrale européenne du jour de chaque opération. Le calendrier fiscal et certaines fêtes ne valent qu'en France.": "Un conto tenuto in un'altra valuta conserva gli importi d'origine; sono convertiti al cambio di riferimento della Banca centrale europea del giorno di ogni operazione. Il calendario fiscale e alcune feste valgono solo in Francia.",
  "Passer ce compte en {devise} ? Ses montants et son solde, tels qu'ils ont été saisis, seront lus dans cette devise.": "Passare questo conto in {devise}? I suoi importi e il suo saldo, così come sono stati inseriti, saranno letti in questa valuta.",
