  "Enseigne retirée": "Negozio rimosso",
  "Un commerce de quartier, un artisan, une association : donne-lui un nom et, s'il a un site, son logo. Pécule le reconnaîtra dans tes opérations comme une grande enseigne.": "Un negozio di quartiere, un artigiano, un'associazione: dagli un nome e, se ha un sito, il suo logo. Pécule lo riconoscerà nei tuoi movimenti come una grande marca.",
