  "Rien ce jour-là.": "Niente quel giorno.",
  "Ce que tu possèdes (comptes, épargne, biens, crypto) moins ce que tu dois encore. Les biens et les crédits communs comptent pour ta part.": "Ciò che possiedi (conti, risparmi, beni, cripto) meno ciò che devi ancora. I beni e i prestiti comuni contano per la tua quota.",
  "Ce qu'il y a sur tes comptes aujourd'hui. Les achats par carte à débit différé pas encore prélevés n'en sont pas déduits.": "Ciò che c'è oggi sui tuoi conti. Gli acquisti con carta ad addebito differito non ancora addebitati non sono detratti.",
  "Revenus du mois moins dépenses du mois. Les mouvements entre tes comptes et les versements d'épargne ne comptent pas.": "Entrate del mese meno spese del mese. I movimenti tra i tuoi conti e i versamenti di risparmio non contano.",
