  "Surveiller mes soldes": "Sorveglia i miei saldi",
  "Pécule te prévient quand un compte est sous son seuil, ou va y passer.": "Pécule ti avvisa quando un conto è sotto la sua soglia, o sta per scenderci.",
  "Seuil": "Soglia",
  "En dessous de ce montant, un compte est signalé. Un montant négatif prévient avant la limite d'un découvert autorisé.": "Sotto questo importo, un conto viene segnalato. Un importo negativo avvisa prima del limite di uno scoperto autorizzato.",
  "Me prévenir": "Avvisami",
  "Combien de jours avant que le compte passe sous le seuil (j = jours).": "Quanti giorni prima che il conto scenda sotto la soglia (j = giorni).",
  "{n} j": "{n} j",
  "Comptes surveillés — décoche un compte pour l'écarter, ou donne-lui un seuil à lui (vide : le seuil ci-dessus).": "Conti sorvegliati — togli la spunta a un conto per escluderlo, o dagli una soglia sua (vuoto: la soglia qui sopra).",
  "Comment c'est calculé : le solde du jour, puis ce qui est attendu sur ce compte d'ici là, en entrées comme en sorties — ce qui y revient chaque mois (prélèvements, virements, salaire) et le relevé d'une carte à débit différé. Les achats du quotidien ne sont pas devinés : c'est une estimation, à lire comme « au mieux ». L'alerte arrive en notification si « Solde bas » est activé sur l'appareil, et se lit aussi sur le calendrier du mois et le tableau de bord. Tu peux demander à l'assistant de changer ces réglages.": "Come viene calcolato: il saldo di oggi, poi ciò che è atteso su questo conto fino ad allora, in entrata come in uscita — ciò che torna ogni mese (addebiti, bonifici, stipendio) e l'estratto di una carta ad addebito differito. Gli acquisti di tutti i giorni non vengono indovinati: è una stima, da leggere come «nel migliore dei casi». L'avviso arriva come notifica se «Saldo basso» è attivo sul dispositivo, e si legge anche nel calendario del mese e nella dashboard. Puoi chiedere all'assistente di cambiare queste impostazioni.",
  "{compte} est sous son seuil : {montant}.": "{compte} è sotto la sua soglia: {montant}.",
  "{compte} passerait à {montant} le {date}, après {cause}.": "{compte} scenderebbe a {montant} il {date}, dopo {cause}.",
  "{compte} passerait à {montant} le {date}.": "{compte} scenderebbe a {montant} il {date}.",
  "Régler l'alerte de solde bas": "Regola l'avviso di saldo basso",
