  "Régler l'alerte": "Regola l'avviso",
  "Aucun compte à suivre pour l'instant.": "Nessun conto da seguire per ora.",
  "La surveillance des soldes est coupée : aucun compte n'est signalé.": "La sorveglianza dei saldi è spenta: nessun conto viene segnalato.",
  "Aucun compte surveillé ne passe sous son seuil dans les {jours} jours.": "Nessun conto sorvegliato scende sotto la sua soglia nei prossimi {jours} giorni.",
  "Comment c'est calculé : le solde du jour, puis ce qui est attendu sur ce compte, en entrées comme en sorties — ce qui y revient chaque mois (prélèvements, virements, salaire) et le relevé d'une carte à débit différé. Un prélèvement dont le jour habituel est passé depuis peu est compté dès aujourd'hui. Les achats du quotidien ne sont pas devinés : c'est une estimation, à lire comme « au mieux ».": "Come viene calcolato: il saldo di oggi, poi ciò che è atteso su questo conto, in entrata come in uscita — ciò che torna ogni mese (addebiti, bonifici, stipendio) e l'estratto di una carta ad addebito differito. Un addebito il cui giorno abituale è passato da poco conta già da oggi. Gli acquisti di tutti i giorni non vengono indovinati: è una stima, da leggere come «nel migliore dei casi».",
  "sous le seuil": "sotto la soglia",
  "{montant} le {date}": "{montant} il {date}",
  "au-dessus du seuil": "sopra la soglia",
  "Pour rester au-dessus du seuil, il manquerait {montant} au plus bas, le {date}.": "Per restare sopra la soglia, mancherebbero {montant} nel punto più basso, il {date}.",
  "En pointillé : le seuil. Le point : le plus bas des jours à venir.": "Tratteggiato: la soglia. Il punto: il minimo dei prossimi giorni.",
  "Mouvements attendus": "Movimenti attesi",
  "Solde après": "Saldo dopo",
  "en retard, attendu d'un jour à l'autre": "in ritardo, atteso da un giorno all'altro",
  "Rien d'attendu sur ce compte d'ici là.": "Niente di atteso su questo conto fino ad allora.",
  "Mois (AAAA-MM)": "Mese (AAAA-MM)",
  "Voir le compte signalé": ["Vedi il conto segnalato", "Vedi i {n} conti segnalati"],
  "Ce qui est attendu sur tes comptes, {n} jour à l'avance": ["Ciò che è atteso sui tuoi conti, {n} giorno in anticipo", "Ciò che è atteso sui tuoi conti, {n} giorni in anticipo"],
  "{n} compte est sous son seuil, ou y passerait dans les {jours} jours.": ["{n} conto è sotto la sua soglia, o ci scenderebbe entro {jours} giorni.", "{n} conti sono sotto la loro soglia, o ci scenderebbero entro {jours} giorni."],
  "Afficher les montants (M)": "Mostra gli importi (M)",
  "Masquer les montants (M)": "Nascondi gli importi (M)",
  "Afficher les montants": "Mostra gli importi",
  "Masquer les montants": "Nascondi gli importi",
  "Masqués": "Nascosti",
  "Visibles": "Visibili",
  "Masquer ou afficher les montants": "Nascondi o mostra gli importi",
  "Ce qui est classé en revenu sur la période ; une entrée sans catégorie compte aussi. Les mouvements entre tes comptes n'en font pas partie.": "Ciò che è classificato come entrata nel periodo; conta anche un'entrata senza categoria. I movimenti tra i tuoi conti non ne fanno parte.",
  "Ce qui est classé en dépense, remboursements déduits ; une sortie sans catégorie compte aussi. Ni l'épargne ni les mouvements entre tes comptes.": "Ciò che è classificato come spesa, rimborsi dedotti; conta anche un'uscita senza categoria. Né il risparmio né i movimenti tra i tuoi conti.",
  "Ce qui est classé en épargne : les versements vers un livret, une assurance-vie, un plan d'épargne.": "Ciò che è classificato come risparmio: i versamenti su un libretto, un'assicurazione vita, un piano di risparmio.",
  "Revenus moins dépenses. L'épargne n'en est pas retirée : c'est ce qui reste avant de mettre de côté.": "Entrate meno spese. Il risparmio non è sottratto: è ciò che resta prima di mettere da parte.",
  "Somme des revenus mensuels nets que tu as renseignés (salaires, loyers…).": "Somma delle entrate mensili nette che hai inserito (stipendi, affitti…).",
  "Somme, ramenée au mois, de tes engagements en cours : la liste plus bas.": "Somma, riportata al mese, dei tuoi impegni in corso: l'elenco più in basso.",
  "Revenus du foyer moins charges fixes : ce qu'il reste chaque mois pour tout le reste.": "Entrate della famiglia meno spese fisse: ciò che resta ogni mese per tutto il resto.",
  "Revenus du foyer moins ce que tu dépenses vraiment par mois, en moyenne sur les trois derniers mois complets.": "Entrate della famiglia meno ciò che spendi davvero al mese, in media sugli ultimi tre mesi completi.",
  "Achats déjà faits avec une carte à débit différé : la banque les prélèvera en une fois, à la date indiquée.": "Acquisti già fatti con una carta ad addebito differito: la banca li addebiterà in una volta, alla data indicata.",
  "Dépenses du mois en cours, remboursements déduits. L'étiquette compare au mois dernier, à la même date.": "Spese del mese in corso, rimborsi dedotti. L'etichetta confronta con il mese scorso, alla stessa data.",
  "Capital qu'il te reste à rembourser sur tes crédits, pour ta part.": "Capitale che ti resta da rimborsare sui tuoi prestiti, per la tua quota.",
  "Valeur estimée moins capital restant dû sur les crédits du bien.": "Valore stimato meno il capitale residuo dei prestiti dell'immobile.",
  "Loyers d'une année rapportés au coût d'acquisition (prix et frais).": "Affitti di un anno rapportati al costo d'acquisto (prezzo e spese).",
  "Densité": "Densità",
  "Aérée": "Ariosa",
  "Compacte": "Compatta",
  "« Compacte » resserre les marges et les lignes pour montrer plus d'opérations par écran, sans réduire le texte. Sur ordinateur seulement ; choix mémorisé sur cet appareil.": "«Compatta» stringe margini e righe per mostrare più operazioni per schermata, senza rimpicciolire il testo. Solo su computer; scelta memorizzata su questo dispositivo.",
  "Tout ce que tu possèdes, avant de retirer ce que tu dois encore.": "Tutto ciò che possiedi, prima di togliere ciò che devi ancora.",
  "Comptes courants et épargne : ce qui se mobilise sans vendre un bien ni un placement.": "Conti correnti e risparmio: ciò che si può usare senza vendere un bene o un investimento.",
  "Compare mon engagement n° {id} « {nom} » à l'offre que je te joins et dis-moi laquelle est la plus avantageuse.": "Confronta il mio impegno n. {id} «{nom}» con l'offerta che ti allego e dimmi qual è la più conveniente.",
