  "Masqué : retiré de ton accueil ; ses opérations restent comptées.": "Nascosto: rimosso dalla tua Home; i suoi movimenti continuano a essere contati.",
  "Affiché de nouveau sur ton accueil.": "Di nuovo visibile nella tua Home.",
  "Hors statistiques : exclu de tes totaux et de tes opérations à classer.": "Fuori dalle statistiche: escluso dai tuoi totali e dai tuoi movimenti da classificare.",
  "Compté de nouveau dans tes statistiques.": "Contato di nuovo nelle tue statistiche.",
  "Régler le compte « {nom} »": "Regolare il conto «{nom}»",
