  "Location ou crédit auto": "Leasing o finanziamento auto",
  "Une seconde rangée de pastilles filtre par nature de contrat : assurance auto, assurance habitation, assurance emprunteur, mutuelle santé, électricité et gaz, box internet, forfait mobile. Elle réunit tous les papiers d'un même contrat (contrat, avenant, attestation, devis concurrent), quel que soit leur domaine. Seules les natures présentes dans ton coffre sont proposées.": "Una seconda fila di etichette filtra per natura del contratto: assicurazione auto, assicurazione casa, assicurazione del mutuo, assicurazione sanitaria, luce e gas, internet di casa, tariffa mobile. Riunisce tutte le carte di uno stesso contratto (contratto, appendice, attestato, preventivo concorrente), qualunque sia il loro ambito. Sono proposte solo le nature presenti nella tua cassaforte.",
  "[[Nature du contrat]], dans [[Modifier]], range le document sous une pastille ou l'en retire. Pécule la reconnaît à la lecture ; corrige-la s'il s'est trompé.": "[[Nature du contrat]], in [[Modifier]], mette il documento sotto un'etichetta o lo toglie. Pécule la riconosce alla lettura; correggila se ha sbagliato.",
  "chercher document retrouver modifier renommer supprimer privé télécharger ouvrir fichier étiquette pastille filtre assurance auto habitation emprunteur mutuelle électricité gaz": "cercare documento ritrovare modificare rinominare eliminare cancellare privato scaricare aprire file etichetta filtro assicurazione auto casa mutuo sanitaria luce gas",
