  "Enveloppe : {plafond} par mois — dépassée de {ecart}": "Busta: {plafond} al mese — superata di {ecart}",
  "Enveloppe : {plafond} par mois — reste {reste}": "Busta: {plafond} al mese — restano {reste}",
  "Épargne non classée": "Risparmio non classificato",
  "[[Répartition]] : le solde de la période, puis trois anneaux — revenus, dépenses, épargne — et la liste de celui que tu choisis, avec une barre par poste. [[Comparer à]] choisit la référence : le mois précédent, la moyenne des trois derniers mois ou le même mois de l'an dernier. Un trait sur une barre marque le plafond de son enveloppe.": "[[Répartition]]: il saldo del periodo, poi tre anelli — redditi, spese, risparmio — e l'elenco di quello che scegli, con una barra per voce. [[Comparer à]] sceglie il riferimento: il mese precedente, la media degli ultimi tre mesi o lo stesso mese dell'anno scorso. Un segno su una barra indica il tetto della sua busta.",
